CREATE TABLE public.wallet_operations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, operation_key uuid NOT NULL, request_hash text NOT NULL, status text NOT NULL DEFAULT 'processing' CHECK (status IN ('processing','completed','unknown')), result jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,operation_key));
GRANT SELECT ON public.wallet_operations TO authenticated;
GRANT ALL ON public.wallet_operations TO service_role;
ALTER TABLE public.wallet_operations ENABLE ROW LEVEL SECURITY;
CREATE POLICY wallet_operation_owner_read ON public.wallet_operations FOR SELECT TO authenticated USING (auth.uid()=user_id);
CREATE TRIGGER wallet_operations_updated BEFORE UPDATE ON public.wallet_operations FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE OR REPLACE FUNCTION public.save_wallet_once(p_user uuid,p_wallet jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE existing jsonb; BEGIN SELECT raw_app_meta_data->'wallet' INTO existing FROM auth.users WHERE id=p_user FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Account unavailable'; END IF; IF existing->'addresses'->>'evm' IS NOT NULL THEN RETURN existing; END IF; UPDATE auth.users SET raw_app_meta_data=coalesce(raw_app_meta_data,'{}'::jsonb)||jsonb_build_object('wallet',p_wallet) WHERE id=p_user; RETURN p_wallet; END $$;
REVOKE ALL ON FUNCTION public.save_wallet_once(uuid,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.save_wallet_once(uuid,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.wallet_encryption_key(p_candidate text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE k text; BEGIN PERFORM pg_advisory_xact_lock(hashtext('ceyo-wallet-encryption')); SELECT api_key INTO k FROM public.provider_api_keys WHERE provider='wallet_encryption' ORDER BY created_at,id LIMIT 1; IF k IS NULL THEN INSERT INTO public.provider_api_keys(provider,api_key) VALUES('wallet_encryption',p_candidate) RETURNING api_key INTO k; END IF; RETURN k; END $$;
REVOKE ALL ON FUNCTION public.wallet_encryption_key(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.wallet_encryption_key(text) TO service_role;
CREATE OR REPLACE FUNCTION public.reserve_free_video_call_minute() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE p text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT plan INTO p FROM public.subscriptions WHERE user_id=auth.uid() AND current_period_end>now(); RETURN jsonb_build_object('allowed',coalesce(p IN ('plus','pro','ultra'),false),'isPaid',coalesce(p IN ('plus','pro','ultra'),false),'seconds',0,'code',CASE WHEN p IN ('plus','pro','ultra') THEN NULL ELSE 'subscription_required' END); END $$;
REVOKE ALL ON FUNCTION public.reserve_free_video_call_minute() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reserve_free_video_call_minute() TO authenticated,service_role;